A demonstration libc-only program that gets the FUSE version:

```c
#define _GNU_SOURCE     /* for asprintf(3gnu) */
#include <errno.h>      /* for errno */
#include <error.h>      /* for error(3gnu) */
#include <fcntl.h>      /* for open(2) and associated flags */
#include <inttypes.h>   /* for uin32_t, PRIu32 */
#include <stdio.h>      /* for printf(3), dprintf(3), asprintf(3gnu) */
#include <stdlib.h>     /* for malloc(3), mkdtemp(3), EXIT_SUCCESS, EXIT_FAILURE */
#include <unistd.h>     /* for read(2), write(2), close(2), getuid(3), getgid(3) */
#include <sys/mount.h>  /* for mount(2), umount(2) */
#include <sched.h>      /* for unshare(2) and associated flags */
#include <string.h>     /* for strdup(3) */
#include <linux/fuse.h> /* for FUSE_INIT, FUSE_MIN_READ_BUFFER, struct fuse_in_header */

/* These 2 strings can be arbitrary values; they are purely cosmetic.  Actually,
 * mount_subtyp being defined at all is optional.  */
#define mount_src "fuse-version"
#define mount_subtyp "fuse-version"

#ifdef mount_subtyp
#  define mount_typ "fuse." mount_subtyp
#else
#  define mount_typ "fuse"
#endif

int main() {
	int fd;
	ssize_t n;
	char *opts;
	char *mount_dst;
	uid_t uid;
	gid_t gid;
	union {
		char unstructured[FUSE_MIN_READ_BUFFER];
		struct {
			struct fuse_in_header header;
			/* Don't use <linux/fuse.h>:`struct fuse_init_in`
			 * because a newer fuse.h might give us a bigger struct
			 * than what an older kernel actually gives us, and that
			 * would break our short-read checks.  */
			struct {
				uint32_t major;
				uint32_t minor;
			} body;
		} structured;
	} req;

	/* Run in a new mount namespace.
	 *
	 * This is important because (1) it allows unprivileged users to sniff
	 * the FUSE version, which is important because systemd-nspawn has an
	 * unprivileged mode; and (2) it prevents against a dangling mount if
	 * for some reason we bail/get-killed before calling unmount().  */

	uid = getuid();
	gid = getgid();
	if (unshare(CLONE_NEWNS|CLONE_NEWUSER) < 0)
		error(EXIT_FAILURE, errno, "unshare");

	fd = open("/proc/self/uid_map", O_WRONLY);
	if (fd < 0)
		error(EXIT_FAILURE, errno, "open /proc/self/uid_map");
	if (dprintf(fd, "0 %d 1", (int)uid) < 0)
		error(EXIT_FAILURE, errno, "write /proc/self/uid_map");
	if (close(fd) < 0)
		error(EXIT_FAILURE, errno, "close /proc/self/uid_map");

	fd = open("/proc/self/setgroups", O_WRONLY);
	if (fd < 0)
		error(EXIT_FAILURE, errno, "open /proc/self/setgroups");
	if (dprintf(fd, "deny") < 0)
		error(EXIT_FAILURE, errno, "write /proc/self/setgroups");
	if (close(fd) < 0)
		error(EXIT_FAILURE, errno, "close /proc/self/setgroups");

	fd = open("/proc/self/gid_map", O_WRONLY);
	if (fd < 0)
		error(EXIT_FAILURE, errno, "open /proc/self/gid_map");
	if (dprintf(fd, "0 %d 1", (int)gid) < 0)
		error(EXIT_FAILURE, errno, "write /proc/self/gid_map");
	if (close(fd) < 0)
		error(EXIT_FAILURE, errno, "close /proc/self/gid_map");

	/* Get a FUSE handle.  */

	fd = open("/dev/fuse", O_RDWR);
	if (fd < 0)
		error(EXIT_FAILURE, errno, "open /dev/fuse");

	mount_dst = mkdtemp(strdup("/tmp/mountpoint.XXXXXX"));
	if (mount_dst == NULL)
		error(EXIT_FAILURE, errno, "mkdtemp");
	if (asprintf(&opts, "fd=%i,rootmode=40000,user_id=0,group_id=0", fd) < 0)
		error(EXIT_FAILURE, errno, "asprintf");
	if (mount(mount_src, mount_dst, mount_typ, 0, opts) < 0)
		error(EXIT_FAILURE, errno, "mount");
	free(opts);

	/* Read version information from the FUSE handle.  */

	n = read(fd, &req.unstructured, sizeof req);
	if (n < 0)
		error(EXIT_FAILURE, errno, "read /dev/fuse");
	if (n < sizeof req.structured.header)
		error(EXIT_FAILURE, 0, "read /dev/fuse: Short read");
	if (req.structured.header.opcode != FUSE_INIT)
		error(EXIT_FAILURE, 0, "expected opcode=%d (FUSE_INIT), got opcode=%"PRIu32,
		      FUSE_INIT, req.structured.header.opcode);
	if (n < sizeof req.structured)
		error(EXIT_FAILURE, 0, "read /dev/fuse: Short read");
	if (req.structured.header.len < sizeof req.structured.body)
		error(EXIT_FAILURE, 0, "FUSE_INIT request body is too small (%"PRIu32" bytes) to store version information (%zu bytes)",
		      req.structured.header.len, sizeof req.structured.body);

	/* Close the FUSE handle.  */

	if (umount(mount_dst) < 0)
		error(EXIT_FAILURE, 0, "umount %s", mount_dst);
	if (rmdir(mount_dst) < 0)
		error(EXIT_FAILURE, 0, "rmdir %s", mount_dst);
	free(mount_dst);
	if (close(fd) < 0)
		error(EXIT_FAILURE, 0, "close /dev/fuse");

	/* Print and return.  */

	printf("kernel fuse version is %"PRIu32".%"PRIu32"\n",
	       req.structured.body.major, req.structured.body.minor);
	return EXIT_SUCCESS;
}
```
